//mistral-nemo-instruct-2407
//i ask: write a shadertoy checker shader

// Checkerboard Shader with mainImage (Corrected)

#define CHECKER_SIZE 64.0 // Size of the checker pattern (adjust to your liking)

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // Calculate UV coordinates for the checker pattern
    vec2 uv = (fragCoord.xy / iResolution.xy - 0.5) * CHECKER_SIZE; // Normalize and adjust fragment coordinate

    // Create checkerboard pattern using both x and y components of UV
    int checkX = int(floor(uv.x));
    int checkY = int(floor(uv.y));

    // Set output color based on the checker values (black for 0, white for 1)
    fragColor = vec4((checkX & checkY) == 0 ? 0.0 : 1.0, (checkX & checkY) == 0 ? 0.0 : 1.0,
                     (checkX & checkY) == 0 ? 0.0 : 1.0, 1.0);
}
